package edu.riara.edp.week08;
import javafx.application.Application;import javafx.beans.binding.Bindings;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class RegistrationFormDemo extends Application {public void start(Stage s){TextField name=new TextField(),email=new TextField();PasswordField password=new PasswordField();CheckBox terms=new CheckBox("Accept terms");Button submit=new Button("Register");Label status=new Label("Complete the form");name.setPromptText("Name");email.setPromptText("Email");password.setPromptText("Password");submit.disableProperty().bind(Bindings.createBooleanBinding(()->name.getText().isBlank()||!email.getText().matches("[^@ ]+@[^@ ]+\\.[^@ ]+")||password.getText().length()<8||!terms.isSelected(),name.textProperty(),email.textProperty(),password.textProperty(),terms.selectedProperty()));submit.setOnAction(e->status.setText("Validated: "+name.getText()));s.setScene(new Scene(new VBox(12,name,email,password,terms,submit,status),430,300));s.show();}public static void main(String[]a){launch(a);}}